from taf.ul.sc.perf.tc import tc
from taf.ul.sc.perf.db_stats.ue import UEStats
from taf.ul.sc.perf.db_stats.bts.kpi_stats import BTSKPIStats
from taf.ul.sc.perf.db_stats.bts.counters_stats import BTSCountersStats
from taf.ul.sc.perf.util.logger import log_debug_function_info, log_function_status_to_console


class DatabaseDataInterface(object):
    def add_test_results_to_db_stats(self):
        db_data = DatabaseData(log_dir=self.pp.post_dir_path)
        db_data.add_bts_stats()
        db_data.add_ue_stats()


class DatabaseData(object):
    def __init__(self, log_dir):
        self.log_dir = log_dir
        self.add_bts_kpi_stats = BTSKPIStats(log_dir=self.log_dir)
        self.ue_stats = UEStats(log_dir=self.log_dir)
        self.add_bts_counters_stats = BTSCountersStats(log_dir=self.log_dir)

    def add_bts_stats(self):
        if tc.is_feature_enabled("generate_kpi_report"):
            self._add_bts_stats()
            self._add_counters_stats()
        # self._add_bts_benchmark_stats()

    @log_function_status_to_console(msg="Add UE stats to json file", log_hierarchy=2, ignore_exception=True)
    @log_debug_function_info()
    def add_ue_stats(self):
        self.ue_stats.add_kpi_stats()
        self.ue_stats.add_benchmark_stats()

    @log_function_status_to_console(msg="Add BTS KPI to json file", log_hierarchy=2, ignore_exception=True)
    @log_debug_function_info()
    def _add_bts_stats(self):
        self.add_bts_kpi_stats()

    @log_function_status_to_console(msg="Add BTS counters to json file", log_hierarchy=2, ignore_exception=True)
    @log_debug_function_info()
    def _add_counters_stats(self):
        self.add_bts_counters_stats()
